"use client";

import { loadFont } from "@remotion/google-fonts/Geist";
import type React from "react";
import { useId } from "react";
import { AbsoluteFill, Easing, interpolate } from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import { type RulerScrubElementId, rulerScrubTimeline } from "./timeline";

const { fontFamily: sans } = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});
const display = sans;

export interface RulerScrubProps {
  from?: number;
  to?: number;
  step?: number;
  format?: string | ((value: number) => string);
  label?: string;
  accent?: string;
  /** Color of the label and the landed tick value; overrides the theme ink. */
  ink?: string;
  /** Background fill; "transparent" drops it. */
  background?: string;
  /** Typeface for the numbers and label. Load it yourself; Geist by default. */
  fontFamily?: string;
  /** Frames the ruler takes to scrub to `to`. */
  scrubLength?: number;
  /** Film grain over the scene. */
  grain?: boolean;
  /** Size of the ruler and copy, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  theme?: "dark" | "light";
  speed?: number;
  /**
   * Moves, trims or stretches the fade in, the scrub, the sheen, the lift,
   * the label and the push, by the ids in `./timeline`. Frames on the scene
   * timeline, after `delay` and `speed`.
   */
  timing?: Timing<RulerScrubElementId>;
}

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const SUBDIV = 10;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    stage: "rgba(255,255,255,0.05)",
    fg: "#F3F2EF",
    muted: "#85848A",
    faint: "#46464C",
    major: "rgba(243,242,239,0.7)",
    minor: "rgba(243,242,239,0.26)",
    future: 0.4,
    grain: 0.065,
    hero: (a: number) =>
      `linear-gradient(${172 + a}deg, #fbeee4 0%, #f3d6c0 22%, #b9a6ff 58%, #8a7bff 78%, #5a5ef0 100%)`,
    glow: [
      "color-mix(in oklab, #8a7bff 16%, transparent)",
      "color-mix(in oklab, #3b3fd8 22%, transparent)",
    ],
  },
  light: {
    bg: "#F5F4F0",
    stage: "rgba(255,255,255,0.9)",
    fg: "#121214",
    muted: "#6E6C67",
    faint: "#B9B6AE",
    major: "rgba(18,18,20,0.66)",
    minor: "rgba(18,18,20,0.24)",
    future: 0.45,
    grain: 0.045,
    hero: (a: number) =>
      `linear-gradient(${155 + a}deg, #7a5cff 0%, #b04cd9 30%, #ff3d9a 62%, #ff8a3d 100%)`,
    glow: [
      "color-mix(in oklab, #ff8a3d 10%, transparent)",
      "color-mix(in oklab, #7a5cff 12%, transparent)",
    ],
  },
} as const;

type Palette = (typeof THEMES)[keyof typeof THEMES];

function decimalsOf(step: number) {
  const s = String(step);
  const i = s.indexOf(".");
  return i < 0 ? 0 : Math.min(4, s.length - i - 1);
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={31}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

function Ticks({
  pos,
  steps,
  gap,
  width,
  u,
  h,
  p,
  accent,
  text,
  centerLit,
  heroOut,
  labelSize,
  fg,
  fontFamily,
}: {
  pos: number;
  steps: number;
  gap: number;
  width: number;
  u: number;
  h: number;
  p: Palette;
  accent: string;
  text: (i: number) => string;
  centerLit: number;
  heroOut: number;
  labelSize: number;
  fg: string;
  fontFamily: string;
}) {
  const span = width / 2 / gap + 1;
  const first = Math.floor((pos - span) * SUBDIV);
  const last = Math.ceil((pos + span) * SUBDIV);
  const lines: React.ReactNode[] = [];
  const labels: React.ReactNode[] = [];
  for (let k = first; k <= last; k++) {
    const x = width / 2 + (k / SUBDIV - pos) * gap;
    const major = k % SUBDIV === 0;
    const mid = !major && k % (SUBDIV / 2) === 0;
    const len = h * (major ? 0.075 : mid ? 0.048 : 0.028);
    const future = k / SUBDIV > steps + 1e-6 ? p.future : 1;
    const isHero = k === steps * SUBDIV;
    const lit = isHero ? centerLit : 0;
    lines.push(
      <line
        key={k}
        x1={x}
        x2={x}
        y1={0}
        y2={-len * (1 + lit * 0.35)}
        stroke={lit > 0.5 ? accent : major ? p.major : p.minor}
        strokeWidth={(major ? 1.75 : 1.1) * u * (1 + lit * 0.4)}
        opacity={future}
      />,
    );
    if (major) {
      const i = k / SUBDIV;
      labels.push(
        <div
          key={`t${k}`}
          style={{
            position: "absolute",
            left: x - gap / 2,
            width: gap,
            top: -h * 0.098 - labelSize,
            textAlign: "center",
            fontFamily,
            fontWeight: 500,
            fontSize: labelSize,
            lineHeight: 1,
            letterSpacing: "-0.005em",
            fontVariantNumeric: "tabular-nums",
            color: isHero ? fg : p.muted,
            opacity: future * (isHero ? 1 - heroOut : 1),
          }}
        >
          {text(i)}
        </div>,
      );
    }
  }
  return (
    <>
      <svg
        width={width}
        height={h * 0.12}
        viewBox={`0 ${-h * 0.12} ${width} ${h * 0.12}`}
        style={{
          position: "absolute",
          left: 0,
          top: -h * 0.12,
          overflow: "visible",
        }}
        aria-hidden
      >
        {lines}
      </svg>
      {labels}
    </>
  );
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function RulerScrub(props: RulerScrubProps) {
  const {
    from = 2012,
    to = 2026,
    step = 1,
    format = "{value}",
    label = "The year launch videos became code",
    accent = "#3B5BFD",
    ink,
    background,
    fontFamily = display,
    grain = true,
    scale = 1,
    delay = 0,
    theme = "dark",
    speed = 1,
    timing,
  } = props;
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width, height, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    rulerScrubTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const enterEl = tl.get("enter");
  const scrub = tl.get("scrub");
  const sheenEl = tl.get("sheen");
  const liftEl = tl.get("lift");
  const labelEl = tl.get("label");
  const pushEl = tl.get("push");
  const u = height / 720;
  const p: Palette = THEMES[theme];
  const fg = ink ?? p.fg;
  const stage =
    background === "transparent" ? "transparent" : (background ?? p.bg);
  const inc = step > 0 ? step : 1;
  const steps = Math.max(1, Math.round((to - from) / inc));
  const dec = decimalsOf(inc);
  const fmt = (v: number) => {
    const n = v.toFixed(dec);
    return typeof format === "function"
      ? format(Number(n))
      : format.replace("{value}", n);
  };
  const text = (i: number) => fmt(from + i * inc);

  const gap = Math.max(width * 0.115, 96 * u);
  const scrubAt = (f: number) => {
    const x = Math.min(1, Math.max(0, (f - scrub.start) / scrub.length));
    const main = (1 - (1 - x) ** 3) * 0.93 + x * 0.07;
    if (f <= scrub.end) return steps * main;
    const dt = f - scrub.end;
    const v0 = (0.07 * steps) / scrub.length;
    return steps + (v0 / 0.9) * Math.sin(dt * 0.9) * Math.exp(-dt * 0.5);
  };
  const pos = scrubAt(t);
  const vel = (scrubAt(t) - scrubAt(t - 1)) * gap;
  const ghost = interpolate(Math.abs(vel), [8 * u, 60 * u], [0, 1], CLAMP);

  const liftAt = (f: number) =>
    interpolate(f, [liftEl.start, liftEl.end], [0, 1], {
      ...CLAMP,
      easing: EASE_IO,
    });
  const lift = liftAt(t);
  // Whether `value(f)`, in px, moves by more than a thousandth of a pixel
  // into or out of this frame. The eases here are flat at their ends, so a
  // progress threshold would drop the tilt while text still crosses pixels.
  const moves = (value: (f: number) => number) =>
    Math.abs(value(t) - value(t - speed)) > 1e-3 ||
    Math.abs(value(t + speed) - value(t)) > 1e-3;
  const rulerY = interpolate(lift, [0, 1], [height * 0.56, height * 0.68]);
  // Layout rounds a box and a baseline to whole pixels, so the ruler stays
  // laid out where it waits through the scrub and the lift is a transform,
  // there all its life: exactly 0 before it starts, and never handed back to
  // layout, which would snap its labels by what the rounding takes.
  const rulerY0 = height * 0.56;
  const liftPx = (f: number) => height * 0.12 * liftAt(f);
  // Its labels scrub sideways by layout right up to the lift and into it, so
  // they lean from the first frame: a lean that came on with the lift would
  // jump them on a frame where they already move.
  const rulerShift = `translateY(${liftPx(t)}px)${glide(
    moves(liftPx) || moves((f) => scrubAt(f) * gap),
  )}`;
  const centerLit = interpolate(
    t,
    [scrub.end + scrub.beat("litAt"), scrub.end + scrub.beat("lit")],
    [0, 1],
    CLAMP,
  );
  const heroOut = interpolate(lift, [0, 0.06], [0, 1], CLAMP);
  const enter = interpolate(t, [enterEl.start, enterEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const flash = interpolate(
    t,
    [
      scrub.end + scrub.beat("flashAt"),
      scrub.end + scrub.beat("flashPeak"),
      scrub.end + scrub.beat("flash"),
    ],
    [0, 1, 0],
    CLAMP,
  );
  const blur = Math.min(8 * u, Math.max(0, Math.abs(vel) - 6 * u) * 0.11);
  const blurId = `b${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;

  const labelSize = 21 * u;
  const heroSize = Math.min(height * 0.34, width * 0.2);
  const heroScale0 = labelSize / heroSize;
  const heroStartY = rulerY - height * 0.098 - labelSize * 0.5;
  const heroEndY = height * 0.34;
  // The hero is laid out where it lands and rides up by transform.
  const heroDrop = (heroStartY - heroEndY) * (1 - lift);
  const heroScaleAt = (f: number) =>
    interpolate(liftAt(f), [0, 1], [heroScale0, 1]) *
    interpolate(f, [pushEl.start, pushEl.end], [1, 1.02], CLAMP);
  const heroScale = heroScaleAt(t);
  // Weighed by half the hero's width, its furthest glyph from the centre;
  // the climb moves with `lift`.
  const heroMoving =
    moves((f) => heroScaleAt(f) * heroSize * 1.2) ||
    moves((f) => (heroStartY - heroEndY) * (1 - liftAt(f)));
  const heroWeight = interpolate(lift, [0, 1], [450, 500]);
  const sheen = interpolate(t, [sheenEl.start, sheenEl.end], [-4, 4], CLAMP);

  const markTop = -height * 0.075 * (1 + centerLit * 0.35) - 6 * u;
  const markBottom = height * 0.034;

  const labelInAt = (f: number) =>
    interpolate(f, [labelEl.start, labelEl.end], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
  const labelIn = labelInAt(t);
  const labelMoving = moves((f) => (1 - labelInAt(f)) * 14 * u);

  const ghosts = [0.5, 1];
  const fade =
    "linear-gradient(90deg, transparent 0%, #000 22%, #000 78%, transparent 100%)";
  const tickProps = {
    pos,
    steps,
    gap,
    width,
    u,
    h: height,
    p,
    accent,
    text,
    labelSize,
    fg,
    fontFamily,
  };

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          background: [
            `radial-gradient(ellipse 42% 46% at ${46 + sheen}% ${36 - 6 * (1 - lift)}%, ${p.glow[0]}, transparent 72%)`,
            `radial-gradient(ellipse 70% 50% at 50% 100%, ${p.glow[1]}, transparent 72%)`,
            `radial-gradient(ellipse 60% 60% at 50% 48%, ${p.stage}, transparent 75%)`,
          ].join(", "),
        }}
      />
      <ScaleLayer scale={scale}>
        <svg width={0} height={0} style={{ position: "absolute" }} aria-hidden>
          <filter id={blurId} x="-10%" y="-10%" width="120%" height="120%">
            <feGaussianBlur stdDeviation={`${blur} 0`} />
          </filter>
        </svg>
        <div
          style={{
            position: "absolute",
            left: 0,
            top: rulerY0 - height * 0.25,
            width,
            height: height * 0.3,
            transform: rulerShift,
            opacity: enter,
            maskImage: fade,
            WebkitMaskImage: fade,
          }}
        >
          <div
            style={{
              position: "absolute",
              left: 0,
              top: height * 0.25,
              width,
              height: Math.max(1, u),
              background: p.minor,
            }}
          />
          <div
            style={{
              position: "absolute",
              inset: 0,
              filter: blur > 0.4 ? `url(#${blurId})` : undefined,
            }}
          >
            <div style={{ position: "absolute", left: 0, top: height * 0.25 }}>
              {ghosts.map((g) =>
                ghost > 0.01 ? (
                  <div
                    key={g}
                    style={{
                      position: "absolute",
                      left: 0,
                      top: 0,
                      opacity: ghost * 0.22 * (1.25 - g),
                      transform: `translateX(${vel * g * 0.7}px)`,
                    }}
                  >
                    <Ticks {...tickProps} centerLit={0} heroOut={0} />
                  </div>
                ) : null,
              )}
              <div style={{ position: "absolute", left: 0, top: 0 }}>
                <Ticks {...tickProps} centerLit={centerLit} heroOut={heroOut} />
              </div>
            </div>
          </div>
        </div>

        <div
          style={{
            position: "absolute",
            left: width / 2 - u,
            top: rulerY0 + markTop,
            transform: rulerShift,
            width: 2 * u,
            height: markBottom - markTop,
            background: accent,
            borderRadius: u,
            opacity: enter,
          }}
        />
        <div
          style={{
            position: "absolute",
            left: width / 2 - 4.5 * u,
            top: rulerY0 + markBottom - 4.5 * u,
            transform: rulerShift,
            width: 9 * u,
            height: 9 * u,
            borderRadius: 9 * u,
            background: accent,
            opacity: enter,
            boxShadow: `0 0 0 ${flash * 7 * u}px ${accent}2E`,
          }}
        />

        <div
          style={{
            position: "absolute",
            left: 0,
            width,
            top: heroEndY,
            height: 0,
            transform: `translateY(${heroDrop}px)`,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            opacity: heroOut,
          }}
        >
          <div
            style={{
              fontFamily,
              fontWeight: heroWeight,
              fontSize: heroSize,
              lineHeight: 1,
              letterSpacing: `${interpolate(lift, [0, 1], [-0.005, -0.05])}em`,
              fontVariantNumeric: "tabular-nums",
              color: "transparent",
              backgroundImage: p.hero(sheen),
              WebkitBackgroundClip: "text",
              backgroundClip: "text",
              padding: "0.08em 0.06em",
              whiteSpace: "nowrap",
              transform: `scale(${heroScale})${glide(heroMoving)}`,
            }}
          >
            {text(steps)}
          </div>
        </div>

        <div
          style={{
            position: "absolute",
            left: 0,
            width,
            top: height * 0.83,
            display: "flex",
            justifyContent: "center",
            fontFamily,
            fontWeight: 400,
            fontSize: 28 * u,
            letterSpacing: "-0.015em",
            color: fg,
            opacity: labelIn,
            transform: `translateY(${(1 - labelIn) * 14 * u}px)${glide(labelMoving)}`,
          }}
        >
          {label}
        </div>
      </ScaleLayer>
      {grain ? <Grain opacity={p.grain} /> : null}
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The ruler scrub: the ruler fading in, the scrub easing along to the last
// value (lighting the centre mark and flashing as it lands), the slow sheen
// across the hero, the ruler lifting away as the value grows into the hero,
// the label rising in and the hero's slow push. Frames on the 30 fps scene
// timeline, after `delay` and `speed`. The ids are public: a saved `timing`
// prop refers to them.

export type RulerScrubElementId =
  | "enter"
  | "scrub"
  | "sheen"
  | "lift"
  | "label"
  | "push";

export interface RulerScrubTimingProps {
  scrubLength?: number;
}

const SCRUB_END = 70;

// `scrub` runs the ruler to the last value over its length, then rings into
// place. Its `litAt`/`lit` (the centre mark lighting) and `flashAt`/
// `flashPeak`/`flash` (the landing flash) are counted from the scrub's END.
// `sheen`, `lift` and `label` follow the scrub; `push` follows the lift.
export const rulerScrubTimeline = defineTimeline<
  RulerScrubElementId,
  RulerScrubTimingProps
>(({ scrubLength = SCRUB_END }): TimelineElement<RulerScrubElementId>[] => [
  { id: "enter", lane: "Ruler", label: "fade in", start: 0, length: 10 },
  {
    id: "scrub",
    lane: "Ruler",
    label: "scrub",
    start: 0,
    length: scrubLength,
    beats: { litAt: -4, lit: 2, flashAt: -2, flashPeak: 1, flash: 14 },
  },
  {
    id: "sheen",
    lane: "Hero",
    label: "sheen",
    start: scrubLength,
    length: 110,
    follows: "scrub",
  },
  {
    id: "lift",
    lane: "Ruler",
    label: "lift",
    start: scrubLength + 6,
    length: 32,
    follows: "scrub",
  },
  {
    id: "label",
    lane: "Label",
    label: "label",
    start: scrubLength + 30,
    length: 24,
    follows: "scrub",
  },
  {
    id: "push",
    lane: "Hero",
    label: "push",
    start: scrubLength + 38,
    length: 72,
    follows: "lift",
  },
]);
